```bash
cd /home/vscode/nullness-benchmarks/zuul && \
python - << 'PYEOF'
from pathlib import Path

path = Path("zuul-core/src/main/java/com/netflix/zuul/netty/server/ssl/SslHandshakeInfoHandler.java")
